export interface DataTableBaseProps extends WithChildren, DataTestId {
  /**
   * Memoized version of the table data (use React.useMemo). If you
   * don't use this, no functionality is guaranteed.
   *
   * Note: Data should not contain any JSX. See custom cell renderers
   * and formatters for the purpose of customizing and formatting
   * output (SingleColumn.cell and SingleColumn.formatter).
   */
  data: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any

  /** Memoized version of the column definitions (use React.useMemo). If you
   * don't use this, no functionality is guaranteed.
   */
  columns: TableColumn[];

  /** Height of the table, overflowing row content is virtualized. */
  height?: number;

  /**
   * Enables sorting for all columns which do not have it explicitly
   * disabled with the `disableSortBy` prop on the column entry.
   *
   * @defaultValue false
   */
  sortable?: boolean;

  /**
   * Displays a loading indicator while the table's data and columns are being loaded.
   *
   * @defaultValue false
   */
  loading?: boolean;

  /**
   * Enables row selection. Adds an extra column with appropriate checkboxes.
   *
   * Note: When row selection is used with in combination with pagination, every
   * page change or page size change will reset the selected rows. This is an
   * intentional design decision and the reasoning behind it is that you may not
   * know (or may forget) what you have selected on a different page (especially
   * with very large data sets or if you selected something on a completely different
   * page). For critical actions like deleting rows this would lead to undesired
   * behavior and issues, so it avoids this problem.
   *
   * @defaultValue false
   */
  selectableRows?: boolean;

  /** Sorts the table initially by this column and changes it on demand. */
  sortBy?: TableSortingRule;

  /**
   * Enables resizing for all columns within the table.
   *
   * @defaultValue false
   */
  resizable?: boolean;

  /**
   * Configures the visual look of DataTable.
   *
   * @defaultValue 'default'
   */
  variant?: TableVariantConfig | 'default';

  /**
   * Configures the thresholds used for the rows highlighting.
   */
  rowThresholds?: ThresholdExtended[];

  /**
   * Enables DataTable to use the full width of its container.
   *
   * @defaultValue false
   */
  fullWidth?: boolean;

  /**
   * Enables line breaking (breaking long text in multiple lines) for all column cells in the table.
   * When set to `true` content of the cell is wrapped,
   * when set to `false` content is truncated.
   *
   * @defaultValue false
   */
  lineWrap?: boolean;

  /**
   * Enables column virtualization for the table.
   * Only the visible columns plus an additional five columns on either side will be rendered to improve performance.
   *
   * @defaultValue false
   */
  columnVirtualization?: boolean;

  /**
   * Called when the column is resized.
   * @param columnWidths - widths of columns which have been resized up to now.
   */
  onColumnResize?: (columnWidths: { [columnId: string]: number }) => void;

  /**
   * Called when table data was downloaded (programmatically or via the toolbar).
   * @param subset - indicates which data was downloaded (all data, current page, selected rows)
   */
  onDownloadData?: (subset: 'all' | 'page' | 'selected') => void;
}
export interface DataTableOnSortPropsWithChange {
  /**
   * This callback serves a dual purpose:
   * 1. Monitor changes in sorting
   * 2. For implementing custom sorting logic instead of the default.
   *
   * It gets invoked when a column is meant to be sorted or when the sorting is reset.
   * When this property is set, the DataTable's built-in sorting is disabled by default,
   * placing the responsibility for sorting in the hands of the callback handler.
   *
   * Alternatively, if you wish to retain the default sorting behavior, you can achieve
   * this by setting the 'enableDefaultSort' property to 'true'.
   */
  onSortChange: (
    columnId: string,
    direction: 'ascending' | 'descending' | 'unset',
  ) => void;

  /**
   * This property is intended to be used in conjunction with the 'onSortChange()'
   * callback to enable or disable the built-in sorting behavior of the DataTable.
   * By default, its value is set to 'false', which means you need to implement
   * your own sorting logic.
   *
   * If you wish to use the 'onSortChange()' callback without custom sorting and
   * instead rely on DataTable's built-in sorting, set this property to 'true'.
   *
   * @defaultValue false
   */
  enableDefaultSort?: boolean;
}

